+                "size": 0,
+                "aggs": {
+                    "pod_name": {
+                        "terms": {
+                            "field": "k8s.pod.name",
+                            "order": { "_key": "asc" }
+                        },
+                        "aggs": {
+                            "max_tx": {
+                                "max": {
+                                    "field": "k8s.pod.network.tx"
+                                }
+                            },
+                            "max_rx": {
+                                "max": {
+                                    "field": "k8s.pod.network.rx"
+                                }
+                            }
+                        }
+                    }
+                }
+            }
